// Client-side best-effort region detection for the login "Auth region"
// dropdown. This only seeds a sensible default — the user can always override
// it, and the post-login cross-region reconciliation in prepare-dashboard
// corrects a wrong guess against the real profile region. No network, no
// backend call.

import { LocalStorage } from 'quasar';
import {
  AUTH_REGION_STORAGE_KEY,
  type ApiRegion,
} from 'src/pages/api-base-url';

/**
 * Guess the cluster region from the browser timezone. American timezones map
 * to the US cluster; everything else (Europe, Asia, Africa, Oceania) defaults
 * to the EU cluster, which is also DocBits' global default. Same primitive
 * already used in boot/debugCollector.ts.
 */
export function detectRegionFromTimezone(): ApiRegion {
  try {
    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone || '';
    if (tz.startsWith('America/')) return 'us';
    if (tz === 'Pacific/Honolulu' || tz === 'Pacific/Pago_Pago') return 'us';
    return 'eu';
  } catch {
    return 'eu';
  }
}

/**
 * Region to pre-select in the login dropdown. Precedence mirrors the language
 * detection in boot/tolgee.js:
 *   1. a deliberately persisted choice (returning user, or set by a prior
 *      cross-region reroute) — read raw so a stored 'eu' is distinguished from
 *      "nothing stored" (getCurrentAuthRegion() masks null as 'eu'),
 *   2. otherwise the timezone heuristic,
 *   3. otherwise 'eu'.
 */
export function getInitialAuthRegion(): ApiRegion {
  const stored = LocalStorage.getItem(AUTH_REGION_STORAGE_KEY);
  if (stored === 'us' || stored === 'eu') return stored;
  return detectRegionFromTimezone();
}
