<template>
  <AuthLayout :loading="processing" :showInfoPanel="!isRuizUrl">
    <AuthCard :title="$t('login_welcome_back') || 'Welcome Back'" :error="display_error ? error_message : ''"
      :dismissible-error="true" @dismiss-error="clearError">
      <!-- Ruiz SSO section -->
      <div v-if="isRuizUrl" class="ruiz-sso-section">
        <img src="/images/ruiz/sso.svg" alt="Sign in with SSO" role="button" tabindex="0" class="ruiz-sso-image"
          @click="microsoftLogin()" @keyup.enter="microsoftLogin()" />
        <AuthDivider />
      </div>

      <!-- Email input -->
      <div class="auth-input-wrapper">
        <q-input ref="emailInput" v-model="email" dense outlined :label="$t('email')"
          data-test="email-input" aria-label="Email address" class="w-full" :rules="[val => validateEmailField(val)]"
          @keyup.enter="enterS" @blur="onEmailBlur" />
        <p v-if="emailError" class="auth-field-error">{{ emailError }}</p>
      </div>

      <!-- Password input -->
      <div class="auth-input-wrapper">
        <q-input v-model="password" dense outlined :label="$t('password')" :type="showPassword ? 'text' : 'password'"
          data-test="password-input" aria-label="Password" class="w-full" @keyup.enter="enterS">
          <template v-slot:append>
            <button type="button" class="password-toggle" @click="toggleShow"
              data-test="show-password-button"
              :aria-label="showPassword ? 'Hide password' : 'Show password'">
              <Icon :icon="showPassword ? 'mdi:eye-off-outline' : 'mdi:eye-outline'"
                class="size-5 text-muted-foreground" />
            </button>
          </template>
        </q-input>
        <p v-if="passwordError" class="auth-field-error">{{ passwordError }}</p>
      </div>

      <!-- Remember me + Forgot password -->
      <div class="flex items-center justify-between">
        <q-checkbox v-model="rememberMe" :label="$t('remember_me')" color="primary" dense data-test="remember-me-checkbox" />
        <button class="auth-link text-sm text-primary cursor-pointer hover:underline" @click="onResetPW()">{{
          $t('forgot_password') }}</button>
      </div>

      <div v-if="showRegionDropdown" class="auth-region-row">
        <q-select
          v-model="selectedAuthRegion"
          :options="regionOptions"
          :label="$t('login_auth_region_label')"
          dense
          outlined
          options-dense
          emit-value
          map-options
          class="w-full"
          data-test="login-auth-region"
        />
      </div>

      <template #actions>
        <!-- Login button -->
        <q-btn type="submit" unelevated color="primary" text-color="white"
          :disable="processing || start_disable_submit_timer" :label="$t('login_button')" class="auth-submit-btn"
          data-test="login-button" aria-label="Log in" @click="onSubmit()" />

        <!-- Passwordless passkey login (DOCB-13746) — opt-in, password stays as
             recovery. Only shown when the browser supports WebAuthn. -->
        <q-btn v-if="passkeySupported" type="button" outline color="primary" no-caps
          :disable="processing" :label="$t('login_with_passkey')" class="auth-submit-btn q-mt-sm"
          icon="fingerprint" data-test="login-passkey-button" aria-label="Sign in with a passkey"
          @click="loginWithPasskey()" />

        <!-- Lockout timer -->
        <PasswordDisableCounter :start_timer="start_disable_submit_timer"
          :counter_end_time="disable_submit_time as unknown as string" @disableTimerDone="disableTimerDone" />

        <!-- Resend verification email -->
        <div v-if="show_verif_email_btn" class="mt-3">
          <ResendVerifyEmail :email="email" />
        </div>

        <!-- Help text -->
        <p class="mt-3 text-center text-xs text-muted-foreground">
          {{ $t('login_sub_header') }}
          <a class="text-primary cursor-pointer hover:underline" @click="contactPage()">
            {{ $t('login_here') }}
          </a>
        </p>

        <!-- Social login -->
        <div class="social-login-section" :class="isRuizUrl ? 'hide' : ''">
          <AuthDivider />
          <div class="social-login-buttons">
            <GoogleLogin :fullWidth="true" />
            <MicrosoftLogin :fullWidth="true" ref="microsoftLoginRef" />
          </div>
        </div>
      </template>
    </AuthCard>

    <template #footer>
      <div class="text-sm text-muted-foreground">
        {{ $t('no_account') }}
        <a class="text-primary font-medium cursor-pointer hover:underline" @click="user_register">
          {{ $t('register') }}
        </a>
      </div>
      <div class="mt-2">
        <span class="text-xs text-muted-foreground/50 tracking-wide">v{{ appVersion }}</span>
      </div>
    </template>

    <template #info>
      <div class="info-card-content">
        <div class="info-card">
          <img src="/images/docbits.svg" alt="DocBits" class="info-card-logo" />
          <div class="info-card-benefits">
            <div class="info-card-benefit">
              <div class="benefit-dot" />
              <span>{{ $t('analytics_dashboard') }}</span>
            </div>
            <div class="info-card-benefit">
              <div class="benefit-dot" />
              <span>{{ $t('pages.login.ai_agents') }}</span>
            </div>
            <div class="info-card-benefit">
              <div class="benefit-dot" />
              <span>{{ $t('pages.login.new_e_docs') }}</span>
            </div>
            <div class="info-card-benefit">
              <div class="benefit-dot" />
              <a
                target="_blank"
                rel="noopener"
                href="https://docs.docbits.com/overview-and-basics/release-notes"
                class="release-notes-link"
              >{{ $t('many_more') }}</a>
            </div>
          </div>
        </div>
      </div>
    </template>
  </AuthLayout>
</template>

<script lang="ts">
import axios from 'axios';
import cache from 'src/utils/cache';
import { LocalStorage, SessionStorage } from 'quasar';
import cookie from 'src/utils/cookies';
import stringUtil from 'src/utils/string';
import { defineComponent, defineAsyncComponent, ref } from 'vue';
import tokenUtil from 'src/utils/tokenUtil';
import type { dynamicObj } from 'src/pages/assets';
import helperUtil from 'src/utils/helperUtil';
import selectApps from 'src/utils/selectApps';
import { AppVersion } from 'src/utils/app_version';
import {
  api,
  getClientAuthorization,
  getCurrentApiRegion,
  getCurrentAuthRegion,
  getOtherAuthRegion,
  isRegionalStage,
  setApiRegion,
  setAuthRegion,
  type ApiRegion,
} from 'pages/APIs';
import {
  isRetryableRegionLoginError,
  preferErrorWithCode,
} from 'src/services/user/userApiService';
import { getInitialAuthRegion } from 'src/utils/region-detection';
import { userApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions/index';
import { polydocs, settings_users } from 'src/utils/helpLinks';
import { AuthLayout, AuthCard, AuthDivider } from 'src/components/Auth';
import ResendVerifyEmail from 'src/pages/User/ResendVerifyEmail.vue';
import PasswordDisableCounter from 'src/pages/User/Login/PasswordDisableCounter.vue';
import { useDocLockStore, useAuthTokenStore } from 'src/store/main';
import { CONSTANTS } from 'src/constants';
import {
  isOrgSelectionRequired,
  storeOrgSelectionPending,
} from 'src/utils/organization/org-selection-pending';
import {
  isMfaRequired,
  isMfaEnrollmentRequired,
  storeMfaPending,
} from 'src/utils/mfa/mfa-pending';
import { performAuthentication, isWebAuthnSupported } from 'src/utils/mfa/webauthn';

/**
 * PERFORMANCE OPTIMIZATION (Issue #13858)
 *
 * Social login components are lazy-loaded to improve FCP/LCP:
 * - GoogleLogin and MicrosoftLogin are not needed for initial render
 * - They appear below the fold in the "social login" section
 * - Lazy loading reduces initial bundle size by ~20-30KB
 */
const GoogleLogin = defineAsyncComponent(() =>
  import('src/pages/User/SocialMediaLogin/GoogleLogin.vue')
);
const MicrosoftLogin = defineAsyncComponent(() =>
  import('src/pages/User/SocialMediaLogin/MicrosoftLogin.vue')
);

export default defineComponent({
  mixins: [selectApps, helperUtil, tokenUtil, stringUtil, cache, cookie],
  components: {
    AuthLayout,
    AuthCard,
    AuthDivider,
    GoogleLogin,
    MicrosoftLogin,
    ResendVerifyEmail,
    PasswordDisableCounter,
  },
  data() {
    return {
      email: '',
      password: '',
      emailError: '',
      passwordError: '',
      rememberMe: false,
      forgotPW: api.forgot_password_url,
      userlogin: true,
      userregister: false,
      disable_submit_difference: 60,
      isValidatingSession: false,
      appVersion: process.env.APP_VUE_CURRENT_VERSION || '0.0.0',
      // Smart default: persisted choice → timezone heuristic → 'eu'.
      // User can still change it; the dropdown only shows on regional stages.
      selectedAuthRegion: getInitialAuthRegion() as ApiRegion,
      // DOCB-13746: only offer passwordless if the browser can do WebAuthn.
      passkeySupported: isWebAuthnSupported(),
    };
  },
  computed: {
    showRegionDropdown(): boolean {
      return isRegionalStage();
    },
    regionOptions(): Array<{ label: string; value: ApiRegion }> {
      return [
        { label: this.$t('login_auth_region_eu'), value: 'eu' },
        { label: this.$t('login_auth_region_us'), value: 'us' },
      ];
    },
  },
  watch: {
    email() {
      if (this.display_error) {
        this.clearError();
      }
    },
    password() {
      if (this.display_error) {
        this.clearError();
      }
    },
    // Persist the user's region choice immediately so a change made on the login
    // screen is honored when building the auth URL. Only the auth region is set
    // here — setApiRegion() reloads on a region flip and would loop pre-login;
    // the api region is set after a successful login in authenticateUser().
    selectedAuthRegion(region: ApiRegion) {
      if (!this.showRegionDropdown) return;
      setAuthRegion(region);
    },
  },
  mounted() {
    let ruiz_sso = false;
    if (this.$route.query.ruiz_sso && this.$route.query.ruiz_sso === 'true') {
      ruiz_sso = true;
    }

    this.isRuizUrl = window.location.hostname.includes('ruiz') || ruiz_sso;

    // Ruiz is US-only: force 'us' and persist the auth region (not the api
    // region — setApiRegion reloads on flip and would loop here).
    if (this.isRuizUrl && this.showRegionDropdown) {
      this.selectedAuthRegion = 'us';
      setAuthRegion('us');
    }

    this.isUserAlreadyLoggedIn();

    const rememberedEmail = LocalStorage.getItem(CONSTANTS.remembered_email);
    if (rememberedEmail && typeof rememberedEmail === 'string') {
      this.email = rememberedEmail;
      this.rememberMe = true;
    }

    document.addEventListener(
      'social_media_login_after',
      this.socialMediaLoginAfter,
    );
  },
  unmounted() {
    document.removeEventListener(
      'social_media_login_after',
      this.socialMediaLoginAfter,
    );
  },
  methods: {
    async isUserAlreadyLoggedIn() {
      const auth_token_store = useAuthTokenStore();

      try {
        const isLoggedIn = await auth_token_store.isLoggedIn();
        if (isLoggedIn) {
          console.log('[AUTH] User is already logged in, redirecting to dashboard');
          this.afterLoginRedirect(this);
          return;
        }
      } catch (error) {
        console.warn('[AUTH] Session validation failed on login page:', error);
        this.displayError(
          this.$t('session_validation_failed_please_relogin') ||
          'Session validation failed. Please log in again.',
        );
      }

      const eventName = SessionStorage.getItem('event_name');
      if (eventName === 'language_change') {
        console.log('[AUTH] Language change detected - preserving auth state');
        SessionStorage.remove('event_name');
        return;
      }

      const intentionalLogout = LocalStorage.getItem('intentional_logout');
      const hasToken = LocalStorage.getItem('token_details');

      if (intentionalLogout || !hasToken) {
        console.log(
          '[AUTH] Clearing storage - intentional logout:',
          !!intentionalLogout,
          ', has token:',
          !!hasToken,
        );
        this.clearStorageForLogout();
      } else {
        console.log('[AUTH] Preserving storage - user can retry login without losing data');
      }
    },

    enterS() {
      if (this.start_disable_submit_timer) {
        return;
      }
      this.onSubmit();
    },

    socialMediaLoginAfter(e: any) {
      this.handleSocialMediaRedirect(e.detail);
    },

    toggleShow() {
      this.showPassword = !this.showPassword;
    },

    goCloud() {
      if (!polydocs) return;
      window.open(polydocs);
    },

    goHelp() {
      if (!settings_users) return;
      window.open(settings_users);
    },

    contactPage() {
      window.open('https://docs.docbits.com/');
    },

    user_register() {
      this.$router.push('/register');
    },

    onResetPW() {
      this.$router.push('/forget-password');
    },

    validateEmailField(val: string): boolean | string {
      if (!val) return true;
      const isValid = this.validateEmail(val);
      return isValid ? true : this.$t('invalid_email');
    },

    onEmailBlur() {
      this.email = this.removeSpaces(this.email);
      if (this.$refs.emailInput) {
        (this.$refs.emailInput as any).validate();
      }
    },

    onSubmit() {
      this.email = this.removeSpaces(this.email);
      let isEmailValid = this.validateEmail(this.email);
      if (!isEmailValid) {
        this.emailError = this.$t('invalid_email');
      } else {
        this.emailError = '';
      }

      if (!this.password || this.password == '') {
        this.passwordError = this.$t('password_mandatory');
      } else {
        this.passwordError = '';
      }

      if (!this.emailError && !this.passwordError) {
        this.authenticateUser();
      }
    },

    // Adopt the region the response came from, then route: to the org picker
    // when the auth service withheld the token pending org selection, otherwise
    // into the normal post-login flow. Shared by the first attempt and the
    // cross-region retry, so both handle multi-org login identically.
    finishLogin(response: any, regionForLogin: ApiRegion | undefined) {
      const needsReloadForRegion = !!(
        regionForLogin &&
        (regionForLogin !== getCurrentAuthRegion() ||
          regionForLogin !== getCurrentApiRegion())
      );
      if (regionForLogin) {
        setAuthRegion(regionForLogin);
        setApiRegion(regionForLogin);
      }
      const redirectParam = this.$route.query.redirect
        ? String(this.$route.query.redirect)
        : '';

      // MFA (DOCB-13743): the password was correct but a second factor is
      // required — the auth service withholds the token and returns
      // { mfa_required, mfa_token, methods }. Order is password → MFA →
      // org-selection → token, so this is checked BEFORE org-selection. Hand off
      // to the challenge screen; no afterLoginEvent (no token exists yet).
      if (isMfaRequired(response)) {
        storeMfaPending({
          mfaToken: response.mfa_token,
          methods: response.methods,
          redirect: redirectParam,
          forceFullReload: needsReloadForRegion,
          authRegion: regionForLogin,
        });
        this.processing = false;
        this.$router.push('/mfa-challenge');
        return;
      }

      // Org-enforced MFA, no factor enrolled (DOCB-13959): the auth service
      // withholds the token and returns { mfa_enrollment_required, mfa_token }.
      // There is no second factor to challenge yet, so show the actionable
      // message. Before this branch existed the payload fell through to
      // afterLoginEvent, which stored a token-less "token" and bounced
      // /prepare-dashboard → /login with no message — the silent login bug.
      if (isMfaEnrollmentRequired(response)) {
        this.processing = false;
        this.displayError(this.$t('mfa_enrollment_required_error'));
        return;
      }

      // Multi-Org Login (SD 2860679170 §4.1): >1 org, no default ⇒ the auth
      // service withholds the full token and returns a picker payload. Hand off
      // to the Org-Picker — no afterLoginEvent (no token exists yet to store).
      if (isOrgSelectionRequired(response)) {
        storeOrgSelectionPending({
          selectionToken: response.selection_token,
          organisations: response.organisations,
          redirect: redirectParam,
          forceFullReload: needsReloadForRegion,
        });
        this.processing = false;
        this.$router.push('/select-organisation');
        return;
      }

      // Last-resort guard (DOCB-13959): any other token-less payload (an
      // unknown withheld-token variant, a malformed challenge body, …) must
      // never reach afterLoginEvent — that persists garbage token_details and
      // the router guard then bounces silently back to /login. Log the shape
      // (keys only — never token values) and show a clear error instead.
      if (!response?.access_token) {
        logError(
          '[AUTH] Token endpoint returned neither a token nor a known challenge payload',
          {
            responseKeys:
              response && typeof response === 'object'
                ? Object.keys(response)
                : typeof response,
          },
        );
        this.processing = false;
        this.displayError(this.$t('general_login_error'));
        return;
      }

      this.afterLoginEvent(response, redirectParam, needsReloadForRegion);
    },

    // DOCB-13746: passwordless login. Runs the discoverable-credential ceremony
    // from this click (WebAuthn needs a user gesture), then resolves + logs in
    // via /passwordless/verify. No password is sent; on any failure (cancelled,
    // no passkey for this region, …) the password form stays available as
    // recovery. Uses the region the user selected on the form.
    async loginWithPasskey() {
      if (this.processing) return;
      this.processing = true;
      this.clearError();
      const region = this.selectedAuthRegion;
      try {
        const options = await userApiService.webauthnPasswordlessBegin(region);
        const assertion = await performAuthentication(options);
        const response = await userApiService.webauthnPasswordlessVerify(
          options.flow_id,
          assertion,
          region,
          this.rememberMe,
        );
        this.finishLogin(response, region);
      } catch (err: any) {
        this.processing = false;
        // A passkey ceremony error carries a friendly i18n code — show that
        // instead of the raw WebAuthn/w3.org DOMException text.
        if (err?.code) {
          this.error_message = this.$t(err.code) as string;
          this.display_error = true;
        } else {
          this.handleErrorFromApi(err);
        }
      }
    },

    // Attempt login against one region. On success calls finishLogin and returns
    // null; on failure returns the error (never throws) so the caller can decide
    // whether to retry the other region or surface it.
    async attemptRegionLogin(
      data: { username: string; password: string },
      region: ApiRegion | undefined,
    ): Promise<any | null> {
      try {
        const response = await userApiService.login(data, region);
        if (response) {
          this.finishLogin(response, region);
          return null;
        }
        return { message: 'Login API returned empty response' };
      } catch (error: any) {
        return error;
      }
    },

    async authenticateUser() {
      const data = {
        username: this.email,
        password: this.removeSpaces(this.password),
      };
      const regionForLogin = this.showRegionDropdown
        ? this.selectedAuthRegion
        : undefined;

      this.processing = true;
      const error = await this.attemptRegionLogin(data, regionForLogin);
      if (!error) return; // finishLogin already ran

      // Each region has its own user DB, so logging into the wrong region is
      // indistinguishable from bad credentials. On a credential rejection, retry
      // the other region once before surfacing the error.
      if (regionForLogin && isRetryableRegionLoginError(error)) {
        const otherRegion = getOtherAuthRegion(regionForLogin);
        const retryError = await this.attemptRegionLogin(data, otherRegion);
        if (!retryError) return; // retry succeeded, finishLogin already ran

        // The other region's auth server erroring / unreachable is a real
        // problem, not a credential issue — show the generic error.
        if (!isRetryableRegionLoginError(retryError)) {
          logError('[AUTH] Cross-region login retry failed unexpectedly', {
            region: otherRegion,
            status: retryError?.response?.status,
            data: retryError?.response?.data,
            message: retryError?.message,
          });
          this.handleLoginFailed();
          this.displayError(this.$t('general_login_error'));
          this.processing = false;
          return;
        }

        // Both regions rejected: surface the response carrying a specific
        // error_code (e.g. NO_ORGANISATION) over a bare "invalid username or
        // password", so the message is the same whichever region was tried
        // first. Info-level, not error — a rejected login is expected (bad
        // password / no org), unlike the unreachable-region case above.
        logInfo('[AUTH] Login rejected by both regions', {
          primaryStatus: error?.response?.status,
          primaryCode: error?.response?.data?.error_code,
          retryStatus: retryError?.response?.status,
          retryCode: retryError?.response?.data?.error_code,
        });
        this.failLogin(preferErrorWithCode(error, retryError));
        return;
      }

      this.failLogin(error);
    },

    // Shared terminal path for a rejected login: record the failure, surface the
    // error, and stop the spinner.
    failLogin(error: any) {
      this.handleLoginFailed();
      this.handleErrorFromApi(error);
      this.processing = false;
    },

    handleLoginFailed() {
      this.start_disable_submit_timer = false;
      let attempts = (LocalStorage.getItem('login_attempts') as number) || 0;
      LocalStorage.set('login_attempts', ++attempts);
      if (attempts > 3) {
        const disable_time_in_seconds =
          (attempts - 3) * this.disable_submit_difference;
        this.disableSubmit(disable_time_in_seconds);
      }
    },

    disableSubmit(difference = 60) {
      if (difference < 0) {
        difference = this.disable_submit_difference;
      }
      this.start_disable_submit_timer = true;
      this.disable_submit_time = new Date();
      this.disable_submit_time.setSeconds(
        this.disable_submit_time.getSeconds() + difference,
      );
    },

    disableTimerDone() {
      this.start_disable_submit_timer = false;
      this.disable_submit_time = null;
    },

    handleSpecificErrors(data: any) {
      if (!data.hasOwnProperty('error')) return;
      if (data.error === 'email_not_verified') {
        this.show_verif_email_btn = true;
      }
    },

    async afterLoginEvent(tokenInfo: any, redirect = '', forceFullReload = false) {
      try {
        this.processing = true;

        LocalStorage.remove('intentional_logout');

        if (this.rememberMe) {
          LocalStorage.set(CONSTANTS.remembered_email, this.email);
        } else {
          LocalStorage.remove(CONSTANTS.remembered_email);
        }

        const auth_token_store = useAuthTokenStore();
        await auth_token_store.setTokenInLocalStorage(tokenInfo);
        await this.setAuthToken(tokenInfo.access_token);

        this.getUniqueLockId();
        AppVersion.updateVersion();
        this.removeDataFromLocalStorage('selectedSubOrg');

        const redirectUrl = redirect
          ? `/prepare-dashboard?redirect=${redirect}`
          : '/prepare-dashboard';

        logInfo(`Login successful: ${this.email} navigating to dashboard`, {
          event: 'user_login_success',
          userEmail: this.email,
          timestamp: new Date().toISOString(),
          redirectTo: redirectUrl,
          userAgent: navigator.userAgent,
          referrer: document.referrer || 'direct',
          hasToken: !!tokenInfo.access_token,
          tokenType: tokenInfo.token_type || 'Bearer',
        });

        if (forceFullReload) {
          window.location.href = redirectUrl;
          return;
        }
        this.$router.push(redirectUrl);
      } catch (err) {
        this.handleErrorFromApi(err);
      } finally {
        this.processing = false;
      }
    },

    onReset() {
      this.email = '';
      this.password = '';
      this.emailError = '';
      this.passwordError = '';
    },

    async handleSocialMediaRedirect(e: any) {
      try {
        if (!e.access_type || !e.access_token) return;
        this.processing = true;
        let formData = new FormData();
        formData.append('type', e.access_type);
        formData.append('access_token', e.access_token);
        let token = await this.getSocialToken(formData);
        this.afterLoginEvent(token, e.redirect);
      } catch (err: any) {
        this.handleErrorFromApi(err);
        this.processing = false;
      }
    },

    async getSocialToken(formData: FormData) {
      let response: any;

      response = await axios.post(api.social_token, formData, {
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
          Authorization: getClientAuthorization(),
        },
        timeout: 10000,
        timeoutErrorMessage: 'Request timed out',
      });

      const success =
        response.data &&
          response.data.hasOwnProperty('success') &&
          response.data.success === true
          ? true
          : false;
      if (
        !success &&
        response.data.hasOwnProperty('message_code') &&
        response.data.message_code == 'INVALID_AUTHORIZATION_CODE'
      ) {
        throw { message: this.$t('errors_INVALID_AUTHORIZATION_CODE') };
      }

      if (!success && response.data.hasOwnProperty('message')) {
        throw { message: response.data.message };
      }

      if (success) {
        let token = response.data.token as dynamicObj;
        return token;
      }
      return '';
    },

    displayError(message: any) {
      this.display_error = true;
      let error_msg = message;
      if (message == 'Invalid \"username\" or \"password\" in request.') {
        error_msg = this.$t('invalid_user_password');
      }
      if (
        message ==
        'This user does not belong to any Organization. Please contact your administrator'
      ) {
        error_msg = this.$t('user_not_belong_to_org');
      }
      if (
        message ==
        'Email address is not verified. Please verify your email address'
      ) {
        error_msg = this.$t('email_not_verified');
      }
      if (!error_msg) {
        error_msg = this.$t('general_login_error');
      }
      this.error_message = error_msg;
    },

    clearError() {
      this.display_error = false;
      this.error_message = '';
    },

    handleErrorFromApi(error: any) {
      let msg = '';

      if (error?.response) {
        msg = ApiExceptions.getErrorMessage(error.response as dynamicObj);
        this.handleSpecificErrors(error.response.data);
      } else if (error?.message) {
        msg = error.message;
      }

      // Never fail silently (DOCB-13959): even when no message can be derived
      // from the error, surface the generic login error — displayError falls
      // back to general_login_error for an empty message.
      this.displayError(msg);
    },

    microsoftLogin() {
      const microsoftLoginComponent = this.getRefElement(this.$refs.microsoftLoginRef as any);
      if (microsoftLoginComponent && microsoftLoginComponent.oauthSignIn) {
        microsoftLoginComponent.oauthSignIn();
      }
    },
  },
  setup() {
    const doc_lock_store = useDocLockStore();
    const { getUniqueLockId } = doc_lock_store;

    const auth_token_store = useAuthTokenStore();
    const { setAuthToken } = auth_token_store;

    return {
      setAuthToken,
      getUniqueLockId,
      isRuizUrl: ref(false),
      access_token: ref(''),
      access_type: ref('google'),
      display_error: ref(false),
      error_message: ref(''),
      show_verif_email_btn: ref(false),
      processing: ref(false),
      showPassword: ref(false),
      start_disable_submit_timer: ref(false),
      disable_submit_time: ref(null as null | Date),
    };
  },
});
</script>

