import { Cookies } from 'quasar';

export default {
  methods: {
    setDataToCookies(key: string, value: any) {
      Cookies.set(key, value);
    },

    getDataFromCookies(key: string) {
      return Cookies.get(key);
    },

    deleteDataFromCookies(key: string) {
      Cookies.remove(key);
    },
  },
};
